<template>
    <ox-model-panel ref="modelPanel" v-bind="props" :repo="repos.tasks"
            :warning="t('alerts.danger_zone_system_data')">
        <template v-for="name in forwardSlots" :key="name" #[name]="bind">
            <slot :name="name" v-bind="bind"/>
        </template>

        <template #item.status="{item}">
            <v-chip :color="colors[item.status]">{{ item.status }}</v-chip>
        </template>

        <template #item.actions="bind">
            <ox-action-post v-bind="bind"
                icon="mdi-restart" :title="t('actions.task.restart')"
                :repo="repos.tasks" path="restart"
                permission="django_tasks_database.change_dbtaskresult" />
            <slot name="item.actions" v-bind="bind"/>
        </template>

        <template #item.date="{item}">
            <v-chip :title="t('fields.enqueued_at')" color="info">{{ item.enqueued_at }}</v-chip><br>
            <v-chip :title="t('fields.started_at')" color="warning">{{ item.started_at }}</v-chip><br>
            <v-chip :title="t('fields.finished_at')" color="success">{{ item.finished_at }}</v-chip><br>
        </template>

        <template #item.return_value="{item}">
            <p class="mb-3">
                <b>{{ t('ox_tasks.fields.args_kwargs') }}</b><br>
                <code>{{ item.args_kwargs }}</code>
            </p>
            <p v-if="item.return_value">
                <b>{{ t('ox_tasks.fields.return_value') }}</b><br>
                <code>{{ item.return_value }}</code>
            </p>
        </template>
    </ox-model-panel>
</template>
<script setup lang="ts">
/**
 * @component
 * {@link ModelPanel} for tasks management.
 */
import { ref, useSlots, withDefaults } from 'vue'

import { t, filterSlots } from '@oxylus/ox'
import {OxModelPanel, OxActionPost} from '@oxylus/ox/components'
import type {ModelPanelDefinition} from '@oxylus/ox'

import {useTasksModels} from '../composables'

const slots = useSlots()
const forwardSlots = filterSlots(slots, null, {exclude: ['item.actions']})
const repos = useTasksModels()
const modelPanel = ref(null)

const props = withDefaults(defineProps<ModelPanelDefinition>(), {
    /** Name of the panel */
    name: 'tasks',
    /** Headers */
    headers: ['status', 'queue_name', 'task_path', 'priority', 'date', 'return_value'],
})


const colors = {
    'SUCCEEDED': 'success',
    'FAILED': 'error',
    'STARTED': 'warning',
    'NEW': 'info',
}

function refresh(timeout) {
    window.setTimeout(() => {
        modelPanel.value?.list.load()
        refresh(timeout)
    }, timeout)
}

// onMounted(() => refresh(1000))
</script>
